INSERT INTO `BotStrategyDefinitions` VALUES ('a1a11bc3-415d-4a5b-9da4-2e3afac22be5','grid-basic','1.0.0','Grid Trading','Places buy and sell orders in a grid pattern to profit from price oscillations','{\"type\": \"object\", \"required\": [\"gridLevels\", \"lowerBound\", \"upperBound\", \"orderSize\", \"capitalAllocation\"], \"properties\": {\"orderSize\": {\"type\": \"number\", \"minimum\": 0.0001}, \"gridLevels\": {\"type\": \"integer\", \"maximum\": 50, \"minimum\": 2}, \"lowerBound\": {\"type\": \"number\", \"minimum\": 0}, \"upperBound\": {\"type\": \"number\", \"minimum\": 0}, \"rebalanceMode\": {\"enum\": [\"balanced\", \"buy-heavy\", \"sell-heavy\"], \"type\": \"string\"}, \"stopLossPercent\": {\"type\": \"number\", \"minimum\": 0}, \"capitalAllocation\": {\"type\": \"number\", \"minimum\": 100}, \"takeProfitPercent\": {\"type\": \"number\", \"minimum\": 0}}}',NULL,NULL,10,1,'2025-11-10 04:06:27.869694',NULL),('bee7815c-4385-4da7-bd7f-1e3bbf665dc7','momentum-scalping','1.0.0','Momentum Scalping','Detects coins with >3% spike in 5min, buys 100 USDT of most volatile, sells at 6% profit or 3% stop loss','{\"type\": \"object\", \"required\": [\"positionSizeUSDT\", \"takeProfitPercent\", \"stopLossPercent\"], \"properties\": {\"maxDailyLoss\": {\"type\": \"number\", \"default\": 500, \"maximum\": 5000, \"minimum\": 50}, \"minVolume24h\": {\"type\": \"number\", \"default\": 1000000, \"maximum\": 10000000, \"minimum\": 100000}, \"cooldownMinutes\": {\"type\": \"integer\", \"default\": 10, \"maximum\": 60, \"minimum\": 1}, \"stopLossPercent\": {\"type\": \"number\", \"default\": 3, \"maximum\": 20, \"minimum\": 0.5}, \"positionSizeUSDT\": {\"type\": \"number\", \"default\": 100, \"maximum\": 1000, \"minimum\": 10}, \"takeProfitPercent\": {\"type\": \"number\", \"default\": 6, \"maximum\": 50, \"minimum\": 1}, \"excludeStablecoins\": {\"type\": \"boolean\", \"default\": true}, \"spikeThresholdPercent\": {\"type\": \"number\", \"default\": 3, \"maximum\": 20, \"minimum\": 1}, \"detectionWindowMinutes\": {\"type\": \"integer\", \"default\": 5, \"maximum\": 60, \"minimum\": 1}, \"maxConcurrentPositions\": {\"type\": \"integer\", \"default\": 10, \"maximum\": 50, \"minimum\": 1}, \"executionIntervalSeconds\": {\"type\": \"integer\", \"default\": 30, \"maximum\": 300, \"minimum\": 10}}}',NULL,NULL,20,1,'2025-11-10 15:34:03.312428',NULL),('d167bc41-d5aa-4cfe-b66d-d4dc496db3f0','aggressive-forex','1.0.0','Aggressive Forex Style','High-risk strategy with EMA trend following, Martingale recovery, and Pyramiding. Similar to aggressive Forex EAs.','{\"type\": \"object\", \"required\": [\"initialLot\", \"capitalAllocation\", \"cutLossUSD\"], \"properties\": {\"emaShift\": {\"type\": \"integer\", \"default\": 5, \"maximum\": 20, \"minimum\": 0}, \"emaPeriod\": {\"type\": \"integer\", \"default\": 200, \"maximum\": 500, \"minimum\": 10}, \"rsiPeriod\": {\"type\": \"integer\", \"default\": 5, \"maximum\": 50, \"minimum\": 2}, \"cutLossUSD\": {\"type\": \"number\", \"default\": 5000, \"maximum\": 50000, \"minimum\": 100}, \"initialLot\": {\"type\": \"number\", \"default\": 0.01, \"maximum\": 1, \"minimum\": 0.001}, \"rsiOversold\": {\"type\": \"number\", \"default\": 20, \"maximum\": 30, \"minimum\": 5}, \"rsiOverbought\": {\"type\": \"number\", \"default\": 80, \"maximum\": 95, \"minimum\": 70}, \"pyramidEnabled\": {\"type\": \"boolean\", \"default\": true}, \"trailingEnabled\": {\"type\": \"boolean\", \"default\": true}, \"maxPyramidOrders\": {\"type\": \"integer\", \"default\": 10, \"maximum\": 50, \"minimum\": 1}, \"capitalAllocation\": {\"type\": \"number\", \"default\": 10000, \"maximum\": 100000, \"minimum\": 100}, \"martingaleEnabled\": {\"type\": \"boolean\", \"default\": true}, \"maxMartingaleOrders\": {\"type\": \"integer\", \"default\": 10, \"maximum\": 50, \"minimum\": 1}, \"martingaleMultiplier\": {\"type\": \"number\", \"default\": 1.1, \"maximum\": 3, \"minimum\": 1}, \"pyramidLotMultiplier\": {\"type\": \"number\", \"default\": 1, \"maximum\": 2, \"minimum\": 0.5}, \"pyramidTriggerPercent\": {\"type\": \"number\", \"default\": 3, \"maximum\": 10, \"minimum\": 0.1}, \"trailingTriggerPercent\": {\"type\": \"number\", \"default\": 10, \"maximum\": 20, \"minimum\": 0.5}, \"trailingDistancePercent\": {\"type\": \"number\", \"default\": 10, \"maximum\": 20, \"minimum\": 0.5}, \"executionIntervalSeconds\": {\"type\": \"integer\", \"default\": 60, \"maximum\": 3600, \"minimum\": 10}, \"martingaleDistancePercent\": {\"type\": \"number\", \"default\": 4, \"maximum\": 10, \"minimum\": 0.5}}}',NULL,NULL,5,1,'2025-11-10 15:34:03.211090',NULL);
